  screen: { flex: 1, padding: 24, backgroundColor: "#f5f6f8", alignItems: "center", justifyContent: "center" },
  card: { backgroundColor: "#ffffff", padding: 20, borderRadius: 16, alignItems: "center", gap: 8 },
  name: { fontSize: 18, fontWeight: "600", color: "#18181b" },
  price: { fontSize: 16, fontWeight: "bold", color: "#ffffff", backgroundColor: "#2563eb", paddingHorizontal: 12, paddingVertical: 4, borderRadius: 999 },
});

registerRootComponent(App);
